
MERGE INTO "QUICKSQLORDER" "T0" USING (SELECT :p0 AS "CUSTOMERNAME", :p1 AS "CUSTOMERID", :p2 AS "AMOUNT", :p3 AS "STATE", :p4 AS "CREATEDAT", :p5 AS "PAIDAT", :p6 AS "NOTE", :p7 AS "ID" FROM dual UNION ALL SELECT :p8 AS "CUSTOMERNAME", :p9 AS "CUSTOMERID", :p10 AS "AMOUNT", :p11 AS "STATE", :p12 AS "CREATEDAT", :p13 AS "PAIDAT", :p14 AS "NOTE", :p15 AS "ID" FROM dual) "QSRC" ON ("T0"."ID" = "QSRC"."ID") WHEN MATCHED THEN UPDATE SET "T0"."CUSTOMERNAME" = "QSRC"."CUSTOMERNAME", "T0"."CUSTOMERID" = "QSRC"."CUSTOMERID", "T0"."AMOUNT" = "QSRC"."AMOUNT", "T0"."STATE" = "QSRC"."STATE", "T0"."CREATEDAT" = "QSRC"."CREATEDAT", "T0"."PAIDAT" = "QSRC"."PAIDAT", "T0"."NOTE" = "QSRC"."NOTE" WHEN NOT MATCHED THEN INSERT ("CUSTOMERNAME", "CUSTOMERID", "AMOUNT", "STATE", "CREATEDAT", "PAIDAT", "NOTE", "ID") VALUES ("QSRC"."CUSTOMERNAME", "QSRC"."CUSTOMERID", "QSRC"."AMOUNT", "QSRC"."STATE", "QSRC"."CREATEDAT", "QSRC"."PAIDAT", "QSRC"."NOTE", "QSRC"."ID")
